using UnityEngine;using UnityEngine.AI;using System.Collections;using System.IO;
public class HunterSettlementProbe:MonoBehaviour {
 IEnumerator Start(){string dir=Path.GetFullPath("Evidence/hunter-settlement-20261030");Directory.CreateDirectory(dir);var p=GetComponent<DemoMovement>();var a=GetComponent<NavMeshAgent>();var anim=GetComponent<HunterGameplayAnimator>().animator;string file=dir+"/playmode.txt";File.WriteAllText(file,"Unity="+Application.unityVersion+" scene="+gameObject.scene.name+"\nAPI behavior test, no simulated keyboard.\n");yield return new WaitForSeconds(1);
 File.AppendAllText(file,"human="+anim.isHuman+" rootMotion="+anim.applyRootMotion+" onNavMesh="+a.isOnNavMesh+" dodgeDuration="+p.dodgeDuration+" invulnerability="+p.dodgeInvulnerability+" distance="+p.dodgeDistance+"\n");ScreenCapture.CaptureScreenshot(dir+"/spawn.png");Vector3 start=transform.position;var path=new NavMeshPath();Vector3 target=start+transform.forward*2;bool valid=a.CalculatePath(target,path)&&path.status==NavMeshPathStatus.PathComplete;if(valid)a.SetPath(path);yield return new WaitForSeconds(.3f);ScreenCapture.CaptureScreenshot(dir+"/moving.png");yield return new WaitForSeconds(.7f);p.TakeManualControl();File.AppendAllText(file,"pathComplete="+valid+" moved="+Vector3.Distance(start,transform.position)+"\n");start=transform.position;float time=Time.time;bool accepted=p.TryDodge(transform.forward);yield return new WaitForSeconds(.3f);File.AppendAllText(file,"at="+(Time.time-time)+" dodge="+p.IsDodging+" invulnerable="+p.IsInvulnerable+" normalized="+anim.GetCurrentAnimatorStateInfo(0).normalizedTime+" animSpeed="+anim.speed+" state="+anim.GetCurrentAnimatorStateInfo(0).shortNameHash+"\n");ScreenCapture.CaptureScreenshot(dir+"/slow-roll.png");yield return new WaitForSeconds(.35f);File.AppendAllText(file,"at="+(Time.time-time)+" dodge="+p.IsDodging+" normalized="+anim.GetCurrentAnimatorStateInfo(0).normalizedTime+"\n");yield return new WaitForSeconds(.3f);File.AppendAllText(file,"accepted="+accepted+" ended="+!p.IsDodging+" travelled="+Vector3.Distance(start,transform.position)+"\n");ScreenCapture.CaptureScreenshot(dir+"/after-roll.png");}
}
